-- Descripción comercial del producto (la redacta el vendedor; se muestra en la ficha del producto).
-- Se completa para los 78 productos demo de V8 sin pisar una descripción que el vendedor ya haya escrito.

ALTER TABLE producto ADD COLUMN IF NOT EXISTS descripcion TEXT;

UPDATE producto p
SET descripcion = d.texto
FROM (VALUES
 ('Gel Limpiador Purificante Piel Grasa', 'Gel limpiador de uso diario para piel grasa o con tendencia acneica. Su ácido salicílico limpia dentro del poro y la niacinamida ayuda a regular el sebo sin resecar. Aplica sobre el rostro húmedo, masajea 30 segundos y enjuaga, mañana y noche.'),
 ('Limpiador Cremoso Barrera Ceramidas', 'Limpiador en crema que limpia sin arrastrar los lípidos de la piel. Con ceramidas y glicerina que ayudan a mantener la barrera cutánea, ideal para piel seca, sensible o atópica. Masajea sobre la piel húmeda y retira con agua tibia.'),
 ('Espuma Limpiadora Suave Sin Sulfatos', 'Espuma ligera con tensioactivos suaves derivados del coco, sin sulfatos. Limpia el exceso de grasa y el protector solar respetando el pH natural de la piel. Apta para uso diario en todo tipo de piel.'),
 ('Agua Micelar Desmaquillante de Ojos', 'Agua micelar que atrapa el maquillaje y la suciedad sin necesidad de frotar. Fórmula suave pensada para la zona de los ojos y párpados sensibles. Empapa un algodón, apóyalo unos segundos sobre el ojo cerrado y retira.'),
 ('Tónico Exfoliante Ácido Glicólico 7%', 'Tónico exfoliante con ácido glicólico al 7 % que renueva la capa superficial de la piel, mejora la textura y aporta luminosidad. Úsalo de noche sobre la piel limpia, 2 a 3 veces por semana al inicio. Usa protector solar al día siguiente.'),
 ('Peeling AHA 25% + BHA 2%', 'Peeling de uso semanal que combina alfahidroxiácidos y ácido salicílico para una exfoliación intensa: textura más lisa, poros más limpios y tono más uniforme. Aplica una capa fina sobre la piel seca, deja actuar máximo 10 minutos y enjuaga. Máximo una vez por semana; no lo uses sobre piel irritada.'),
 ('Tónico Calmante PHA', 'Tónico con polihidroxiácidos, la familia más suave de exfoliantes, pensado para piel sensible. Afina la textura y aporta hidratación sin la irritación de otros ácidos. Aplica con las manos o un algodón después de limpiar el rostro.'),
 ('Sérum Vitamina C 15% + Ácido Ferúlico', 'Sérum antioxidante con vitamina C pura al 15 % estabilizada con ácido ferúlico y vitamina E. Aporta luminosidad, ayuda a unificar el tono y complementa la protección frente al daño solar. Aplica 3 a 4 gotas cada mañana, antes del protector solar.'),
 ('Sérum Retinol 0,3% Noche', 'Sérum de noche con retinol al 0,3 % para iniciarse en los retinoides. Ayuda a suavizar líneas finas, afinar la textura y unificar el tono con el uso constante. Empieza 2 noches por semana y aumenta poco a poco; usa protector solar de día.'),
 ('Sérum Retinal 0,1% Intensivo', 'Sérum con retinal (retinaldehído) al 0,1 %, un retinoide de acción más rápida que el retinol. Para pieles que ya toleran retinoides y buscan resultados visibles en arrugas y manchas. Úsalo solo de noche y con protector solar al día siguiente.'),
 ('Sérum Bakuchiol Piel Sensible', 'Sérum con bakuchiol, un activo vegetal con efecto similar al retinol pero mejor tolerado por la piel sensible. Mejora la firmeza y la textura sin enrojecer. Se puede usar mañana y noche.'),
 ('Sérum Hialurónico Multinivel', 'Sérum hidratante con ácido hialurónico de varios pesos moleculares que hidratan la piel en distintas capas. Aporta jugosidad y reduce la sensación de tirantez. Aplica sobre la piel ligeramente húmeda y sella con tu crema hidratante.'),
 ('Sérum Antimanchas Tranexámico + Arbutina', 'Sérum despigmentante que combina ácido tranexámico y alfa-arbutina para atenuar manchas solares, melasma y marcas de acné. Úsalo mañana y noche sobre la piel limpia. El protector solar diario es indispensable para ver resultados.'),
 ('Esencia Baba de Caracol 96%', 'Esencia ligera con 96 % de filtrado de secreción de caracol. Hidrata, calma y ayuda a la recuperación de la piel. Aplica después del tónico y antes de la crema, mañana y noche.'),
 ('Sérum Péptidos Antiarrugas', 'Sérum con un complejo de péptidos que apoyan la firmeza y suavizan la apariencia de las arrugas de expresión. Textura ligera que se absorbe rápido. Aplica mañana y noche antes de la crema hidratante.'),
 ('Gel Ácido Azelaico 10%', 'Gel con ácido azelaico al 10 % que ayuda con el acné, el enrojecimiento de la rosácea y las manchas posinflamatorias. Es de los activos mejor tolerados por la piel sensible. Aplica una capa fina una o dos veces al día.'),
 ('Gel Peróxido de Benzoilo 5%', 'Tratamiento localizado con peróxido de benzoilo al 5 % que combate la bacteria del acné. Aplica una capa fina sobre las zonas con brotes, una vez al día. Puede decolorar toallas y ropa; no lo combines con retinoides a la misma hora. Consulta a tu dermatólogo si el acné es moderado o severo.'),
 ('Loción Secante Azufre y Salicílico', 'Loción de acción localizada para granitos puntuales. El azufre y el ácido salicílico ayudan a secar el brote durante la noche. Sin agitar, toma el sedimento rosado con un copito, aplícalo solo sobre el grano y déjalo actuar hasta la mañana.'),
 ('Crema Despigmentante Hidroquinona 4%', 'Crema despigmentante con hidroquinona al 4 % para manchas resistentes. Úsala solo con indicación y seguimiento de un dermatólogo, por periodos limitados y sobre las zonas afectadas. El protector solar diario es obligatorio durante el tratamiento.'),
 ('Mascarilla Arcilla Verde Purificante', 'Mascarilla de arcilla verde que absorbe el exceso de grasa y ayuda a limpiar los poros. Ideal para piel grasa o mixta. Aplica una capa uniforme, deja actuar 10 minutos sin dejar que se seque del todo y retira con agua tibia. Una o dos veces por semana.'),
 ('Mascarilla Nutritiva de Miel y Propóleo', 'Mascarilla cremosa con miel y propóleo que nutre y suaviza la piel seca o apagada. Aplica una capa generosa, deja actuar 15 minutos y retira con agua tibia. Si tienes alergia al propóleo o a productos de la colmena, evítala.'),
 ('Crema Hidratante Barrera Ceramidas', 'Crema hidratante con ceramidas, colesterol y ácidos grasos en la proporción que necesita la barrera de la piel. Repara y protege la piel seca, sensible o atópica. Úsala mañana y noche como último paso de tu rutina.'),
 ('Crema Calmante Cica Centella', 'Crema calmante con Centella asiática y pantenol que alivia la piel irritada o enrojecida y apoya su recuperación. Textura ligera, apta para piel sensible. Aplica sobre el rostro limpio cuantas veces lo necesites.'),
 ('Crema Antiedad Péptidos y Coenzima Q10', 'Crema antiedad con péptidos y coenzima Q10 que ayudan a mejorar la firmeza y a proteger la piel del estrés oxidativo. Textura rica que deja la piel suave y nutrida. Aplica mañana y noche sobre rostro y cuello.'),
 ('Contorno de Ojos Cafeína', 'Contorno de ojos con cafeína que ayuda a desinflamar las bolsas y atenuar las ojeras. Textura en gel fresca que no pesa. Aplica una pequeña cantidad con toques suaves del lagrimal hacia afuera, mañana y noche.'),
 ('Crema Avena Coloidal Piel Atópica', 'Crema emoliente con avena coloidal que calma el picor y la resequedad de la piel atópica. Sin fragancia. Úsala en rostro y cuerpo, idealmente justo después del baño con la piel aún húmeda.'),
 ('Crema Urea 10% Pies y Codos', 'Crema con urea al 10 % que hidrata a fondo y suaviza la piel áspera de pies, codos y rodillas. Aplica una vez al día sobre las zonas secas. No la uses sobre heridas abiertas.'),
 ('Bálsamo Reparador Multiusos', 'Bálsamo oclusivo que protege y repara la piel muy seca o agrietada: labios, cutículas, manos, codos o zonas irritadas. Aplica una capa fina donde lo necesites, cuantas veces quieras.'),
 ('Aceite Facial Rosa Mosqueta', 'Aceite facial de rosa mosqueta prensado en frío, rico en ácidos grasos esenciales. Nutre la piel seca y ayuda a mejorar la apariencia de cicatrices y marcas. Aplica 2 a 3 gotas de noche, como último paso de tu rutina.'),
 ('Protector Solar Mineral FPS 50', 'Protector solar mineral FPS 50 con óxido de zinc y dióxido de titanio. Protección de amplio espectro bien tolerada por la piel sensible. Aplica generosamente 15 minutos antes de exponerte al sol y reaplica cada 2 horas.'),
 ('Fluido Solar Invisible FPS 50+', 'Fluido solar de muy alta protección con textura ultraligera y acabado invisible, ideal para usar a diario bajo el maquillaje. Aplica como último paso de tu rutina de la mañana y reaplica cada 2 horas si estás al aire libre.'),
 ('Protector Solar Spray Playa FPS 30', 'Protector solar en spray para cuerpo, resistente al agua, pensado para piscina y playa. Rocía de forma generosa a unos 15 cm de la piel y extiende con la mano. Reaplica después de nadar o sudar.'),
 ('Gel Aftersun Aloe y Mentol', 'Gel para después del sol con aloe vera y mentol que refresca y calma la piel enrojecida por la exposición solar. Guárdalo en la nevera para un efecto más refrescante. No reemplaza al protector solar.'),
 ('Base Líquida Cobertura Media', 'Base de maquillaje líquida de cobertura media y acabado natural que unifica el tono sin efecto máscara. Aplica con brocha, esponja o los dedos, desde el centro del rostro hacia afuera.'),
 ('Polvo Compacto Matificante', 'Polvo compacto que matifica, fija el maquillaje y controla los brillos durante el día. Incluye espejo, ideal para retoques. Aplica con brocha o borla sobre la zona T.'),
 ('Paleta de Sombras Atardecer', 'Paleta de sombras en tonos cálidos y terrosos, con acabados mate y satinados que se difuminan con facilidad. Perfecta para looks de día y de noche.'),
 ('Labial Mate Larga Duración', 'Labial líquido de acabado mate y alta pigmentación que dura todo el día sin transferirse. Aplica sobre los labios limpios y deja secar un minuto antes de juntarlos.'),
 ('Brillo Labial Volumen', 'Brillo labial con efecto de volumen y acabado jugoso. Úsalo solo o sobre tu labial favorito para dar luz y dimensión a los labios.'),
 ('Máscara de Pestañas Volumen Extremo', 'Máscara de pestañas que aporta volumen y longitud desde la raíz sin grumos. Aplica en zigzag desde la base hacia las puntas. Se retira con desmaquillante de ojos.'),
 ('Bálsamo Labial Reparador Clásico', 'Bálsamo labial reparador que protege los labios secos o agrietados por el frío y el viento. Llévalo contigo y aplícalo cuantas veces lo necesites.'),
 ('Esmalte de Uñas Rojo Pasión', 'Esmalte de uñas rojo intenso de secado rápido y brillo duradero. Aplica dos capas delgadas sobre una base y termina con top coat para mayor duración.'),
 ('Esmalte Semipermanente Gel UV', 'Esmalte semipermanente que cura con lámpara UV/LED y dura hasta tres semanas sin perder brillo. Aplícalo sobre una base para gel y no toques la piel con el producto: los acrilatos pueden causar alergia.'),
 ('Monómero Líquido para Uñas Acrílicas', 'Monómero líquido para construir uñas acrílicas, de uso profesional. Úsalo en un espacio ventilado y evita el contacto con la piel: los acrilatos son una causa frecuente de alergia en manicuristas.'),
 ('Quitaesmalte con Glicerina', 'Quitaesmalte que retira el esmalte con facilidad y, gracias a la glicerina, reseca menos las uñas y cutículas. Empapa un algodón, presiona unos segundos sobre la uña y desliza.'),
 ('Champú Clásico Brillo Total', 'Champú de limpieza profunda para uso frecuente que deja el cabello suelto y con brillo. Aplica sobre el cabello húmedo, masajea el cuero cabelludo y enjuaga.'),
 ('Champú Volumen Sulfatos de Amonio', 'Champú de limpieza intensa que elimina residuos de productos de peinado y aporta volumen al cabello fino o graso. Por su poder de limpieza, no se recomienda para cabello teñido o muy seco.'),
 ('Champú Sin Sulfatos Cabello Teñido', 'Champú sin sulfatos con tensioactivos suaves que limpia sin arrastrar el color. Prolonga la duración del tinte y mantiene el brillo. Ideal para cabello teñido o con tratamientos químicos.'),
 ('Champú Anticaspa Piritiona de Zinc', 'Champú anticaspa con piritiona de zinc que controla la descamación y el picor del cuero cabelludo. Masajea el cuero cabelludo y deja actuar 2 a 3 minutos antes de enjuagar. Úsalo 2 o 3 veces por semana.'),
 ('Champú Medicado Ketoconazol 2%', 'Champú medicado con ketoconazol al 2 % para la caspa intensa y la dermatitis seborreica. Úsalo según la indicación de tu médico: normalmente 2 veces por semana, dejando actuar 3 a 5 minutos.'),
 ('Champú Sulfuro de Selenio 1%', 'Champú con sulfuro de selenio al 1 % que reduce la caspa persistente. Deja actuar 2 a 3 minutos y enjuaga bien. Puede alterar el color del cabello teñido o decolorado.'),
 ('Champú Sólido Natural', 'Champú en barra sin envase plástico, con tensioactivos suaves y aceites vegetales. Frota la barra sobre el cabello húmedo hasta hacer espuma y enjuaga. Rinde hasta 60 lavados.'),
 ('Acondicionador Reparador Keratina', 'Acondicionador con keratina que desenreda, suaviza y ayuda a reparar el cabello dañado. Aplica de medios a puntas después del champú, deja actuar 2 minutos y enjuaga.'),
 ('Mascarilla Capilar Coco y Karité', 'Mascarilla nutritiva con aceite de coco y manteca de karité para cabello seco, rizado o maltratado. Aplica sobre el cabello húmedo de medios a puntas, deja actuar 10 minutos y enjuaga. Una o dos veces por semana.'),
 ('Sérum Capilar Antifrizz Siliconas', 'Sérum capilar con siliconas que sella la cutícula, controla el frizz y aporta brillo inmediato. Aplica unas gotas sobre medios y puntas, con el cabello húmedo o seco.'),
 ('Gel Fijador Efecto Mojado', 'Gel fijador de alta sujeción con efecto mojado para peinados definidos que duran todo el día. Aplica sobre el cabello húmedo o seco y peina a tu gusto.'),
 ('Tónico Capilar Cafeína y Romero', 'Tónico capilar sin enjuague con cafeína y romero que estimula el cuero cabelludo y apoya el crecimiento de un cabello más fuerte. Aplica unas gotas directamente sobre el cuero cabelludo y masajea. No enjuagar.'),
 ('Loción Anticaída Minoxidil 5%', 'Loción con minoxidil al 5 % para la caída del cabello de tipo androgenético. Úsala según la indicación de tu médico: normalmente 1 ml dos veces al día sobre el cuero cabelludo seco. Los resultados se ven después de 3 a 6 meses de uso constante.'),
 ('Aceite Capilar de Ricino y Argán', 'Aceite capilar con ricino y argán que nutre el cabello y las puntas abiertas. Aplica unas gotas de medios a puntas o úsalo como tratamiento antes del lavado.'),
 ('Tinte Permanente Castaño Oscuro 3.0', 'Tinte permanente en crema tono castaño oscuro 3.0 con cobertura total de canas. Haz la prueba de alergia 48 horas antes de cada aplicación, incluso si ya has usado el producto. Mezcla con revelador de 20 volúmenes.'),
 ('Revelador Crema Oxidante 20 Vol', 'Revelador en crema de 20 volúmenes para mezclar con tinte permanente o polvo decolorante. Sigue la proporción de mezcla que indique el fabricante del tinte.'),
 ('Polvo Decolorante 9 Tonos', 'Polvo decolorante que aclara hasta 9 tonos, de uso profesional. Mezcla con revelador y aplica con guantes. No lo apliques el mismo día de un alisado o una permanente.'),
 ('Henna Natural Rojiza', 'Henna 100 % vegetal que tiñe el cabello de tonos rojizos y le aporta cuerpo y brillo. Mezcla con agua tibia hasta formar una pasta, aplica y deja actuar 1 a 3 horas según la intensidad deseada.'),
 ('Kit Permanente Rizos Definidos', 'Kit para hacer permanente y lograr rizos definidos y duraderos. Incluye la loción rizadora y el neutralizante. No lo combines el mismo día con tinte o decoloración: deja pasar al menos dos semanas.'),
 ('Alisado Brasileño de Keratina', 'Tratamiento alisador con keratina que reduce el volumen y el frizz por varias semanas, de uso profesional. Aplícalo en un lugar ventilado y no lo combines el mismo día con tinte o decoloración.'),
 ('Jabón en Barra Glicerina y Coco', 'Jabón en barra tradicional con glicerina y aceite de coco que limpia y deja una sensación suave en la piel. Es alcalino (pH 9,5), por eso no se recomienda para el rostro ni para la piel muy seca o sensible.'),
 ('Jabón Líquido Antibacterial', 'Jabón líquido para manos que limpia y elimina la suciedad en cada lavado. Lava tus manos al menos 20 segundos y enjuaga bien.'),
 ('Gel Antibacterial de Manos 70%', 'Gel desinfectante de manos con 70 % de alcohol para cuando no tienes agua y jabón a mano. Frota las manos hasta que el gel se seque por completo.'),
 ('Crema Corporal Clásica', 'Crema corporal de uso diario que hidrata y suaviza la piel de todo el cuerpo. Aplica después del baño con movimientos circulares.'),
 ('Loción Corporal Karité, Cacao y Mango', 'Loción corporal nutritiva con mantecas de karité, cacao y mango para la piel seca. Deja la piel suave y con un aroma delicado. Aplica después del baño.'),
 ('Aceite Corporal Almendras y Semillas', 'Aceite corporal con almendras dulces y aceites de semillas que nutre la piel seca y le aporta elasticidad. Aplica sobre la piel húmeda al salir de la ducha.'),
 ('Exfoliante Corporal Queratosis Pilar', 'Loción exfoliante corporal con ácido salicílico, ácido láctico y urea, pensada para la queratosis pilar (los "granitos" de brazos y piernas). Aplica a diario sobre las zonas afectadas y usa protector solar si quedan expuestas.'),
 ('Antitranspirante Roll-on 48 h', 'Antitranspirante en roll-on con sales de aluminio que controla el sudor y el olor hasta 48 horas. Aplica sobre la piel limpia y seca, no sobre la piel recién depilada o irritada.'),
 ('Antitranspirante en Barra Invisible', 'Antitranspirante en barra de acabado invisible que no deja manchas blancas en la ropa. Aplica sobre las axilas limpias y secas.'),
 ('Desodorante Natural Sin Aluminio', 'Desodorante sin sales de aluminio que neutraliza el olor sin bloquear el sudor. Con bicarbonato y aceites vegetales. Si tienes la piel sensible, prueba primero en una zona pequeña.'),
 ('Eau de Parfum Jardín de Medianoche', 'Eau de parfum de notas florales y amaderadas, de larga duración. Aplica sobre los puntos de pulso: muñecas, cuello y detrás de las orejas. Contiene alérgenos de fragancia; evítala si eres alérgico a perfumes.'),
 ('Colonia Clásica de Barbería', 'Colonia fresca de notas cítricas y aromáticas inspirada en la barbería clásica. Ideal para el día a día. Contiene alérgenos de fragancia.'),
 ('Bálsamo Aromático del Perú', 'Bálsamo aromático con bálsamo del Perú, de notas cálidas y avainilladas. El bálsamo del Perú es un alérgeno frecuente: evítalo si eres alérgico a fragancias.'),
 ('Roll-on Aceites Esenciales Relajante', 'Roll-on de aromaterapia con aceites esenciales de lavanda y otros de efecto relajante. Aplica sobre las sienes o las muñecas en momentos de estrés. No lo uses sobre la piel irritada ni en niños pequeños.')
) AS d(nombre, texto)
WHERE p.nombre = d.nombre
  AND p.vendedor_id = (SELECT id FROM usuario WHERE email = 'manuel.pinedave@uqvirtual.edu.co')
  AND p.descripcion IS NULL;
